public class ReadCharTests {

    @Test
    public void testReadCharSequentialBasic() throws Exception {
        SimpleCharStream scs = new SimpleCharStream(new StringReader("Hello"));
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 5; i++) {
            sb.append(scs.readChar());
        }
        assertEquals("Hello", sb.toString());
