    @Test
    public void testReadCharLineColumnTracking() throws Exception {
        SimpleCharStream scs = new SimpleCharStream(new StringReader("A\nB"), 1, 1, 4);
        char c1 = scs.readChar();
        assertEquals('A', c1);
        assertEquals(1, scs.line);
        assertEquals(1, scs.column);

        char c2 = scs.readChar();
        assertEquals('\n', c2);
        assertEquals(2, scs.line);
        assertEquals(0, scs.column);

        char c3 = scs.readChar();
        assertEquals('B', c3);
        assertEquals(2, scs.line);
        assertEquals(1, scs.column);
    }

    @Test
    public void testReadCharWithBufferWrap() throws Exception {
        String data = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        SimpleCharStream scs = new SimpleCharStream(new StringReader(data), 1, 1, 8);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < data.length(); i++) {
            sb.append(scs.readChar());
        }
        assertEquals(data, sb.toString());
    }

    @Test(expected = IOException.class)
    public void testReadCharIOExceptionDuringFill() throws Exception {
        SimpleCharStream scs = new SimpleCharStream(new ThrowingReader("XYZ"), 1, 1, 4);
        scs.readChar();
        scs.readChar();
        scs.readChar();
        // The next readChar should trigger IOException from the underlying reader
        scs.readChar();
    }

    private static class ThrowingReader extends Reader {
        private final String data;
        private int pos;
        private boolean threw;

        public ThrowingReader(String data) {
            this.data = data;
            this.pos = 0;
            this.threw = false;
        }

        @Override
        public int read(char[] cbuf, int off, int len) throws IOException {
            if (threw) {
                throw new IOException("boom");
            }
            if (pos >= data.length()) {
                threw = true;
                throw new IOException("boom");
            }
            int n = Math.min(len, data.length() - pos);
            data.getChars(pos, pos + n, cbuf, off);
            pos += n;
            return n;
        }

        @Override
        public void close() {
            // no-op
        }
    }
}

